//! netd — the network's DHCPv4 server, IPv6 router advertiser and resolver, in
//! one process, configured by one generated document.
//!
//! Read `docs/netd-2026-11-26.md` first: it says what this replaces, which four
//! dnsmasq behaviours cost this network days, and what the cutover looks like.
//! The short version:
//!
//!   * it serves exactly the twenty-three directives this network used, and
//!     refuses to grow a line-oriented dialect back (`config/` is one JSON
//!     document, validated strictly, generated by `common/netd/mk-config.nix`);
//!   * the lease table is memory in this process, served as `GET /v1/leases`,
//!     so the dashboard no longer reads a file another daemon writes — that
//!     channel (`machines/gw/lease-reader.nix`) is what froze the lease page for
//!     two and a half days in 2026-10;
//!   * the router advertisement timer is a comparison in a loop, not a timer
//!     inside a daemon, so a link flap cannot stop it (`ra.rs`).
//!
//! ## The verbs
//!
//! ```text
//! netd run     --config /etc/netd/config.json    # the daemon (the default)
//! netd check   --config …                        # validate, then print what it would do
//! netd explain --config … --interface vlan225 --mac c8:d3:ff:a5:b2:25
//! netd probe   --config … --interface vlan226    # a whole DHCP cycle against whatever answers
//! netd leases  --config …                        # the snapshot on disk
//! netd query   --server 127.0.0.1:53 --name grafana.int.leighhack.org
//! netd version
//! ```
//!
//! Every one of those except `run`/`probe` needs no privileges, which is what
//! makes `check` usable as a build-time gate and `explain` usable in a shell
//! where nobody wants to be root.

mod api;
mod config;
mod dhcp;
mod dhcp_server;
mod dns;
mod dns_server;
mod lease;
mod probe;
mod ra;
mod report;
mod stats;
mod sys;
mod util;

use config::Config;
use dns_server::Dns;
use lease::LeaseDb;
use stats::Stats;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

fn main() {
    if let Err(e) = dispatch() {
        eprintln!("netd: {e}");
        std::process::exit(1);
    }
}

struct Args {
    command: String,
    flags: BTreeMap<String, String>,
    switches: Vec<String>,
}

impl Args {
    fn parse() -> Result<Args, String> {
        let argv: Vec<String> = std::env::args().skip(1).collect();
        let mut command = "run".to_string();
        let mut flags = BTreeMap::new();
        let mut switches = Vec::new();
        let mut it = argv.into_iter();
        let mut first = true;
        while let Some(a) = it.next() {
            if a.starts_with("--") {
                let name = a.trim_start_matches("--").to_string();
                // `--flag value`, and `--flag` on its own for the booleans.
                match it.next() {
                    Some(v) if !v.starts_with("--") => {
                        flags.insert(name, v);
                    }
                    Some(v) => {
                        switches.push(name);
                        // Put the next flag back by handling it in the same pass:
                        // an iterator cannot push back, so treat it as a switch
                        // and recurse into the loop by inserting it here.
                        let mut rest = vec![v];
                        rest.extend(it);
                        it = rest.into_iter();
                    }
                    None => switches.push(name),
                }
            } else if first {
                command = a;
                first = false;
            } else {
                return Err(format!(
                    "unexpected argument `{a}` — options are --name value"
                ));
            }
        }
        Ok(Args {
            command,
            flags,
            switches,
        })
    }

    fn flag(&self, name: &str) -> Option<&str> {
        self.flags.get(name).map(String::as_str)
    }

    fn req(&self, name: &str) -> Result<&str, String> {
        self.flag(name)
            .ok_or_else(|| format!("--{name} is required (try --help)"))
    }

    fn has(&self, name: &str) -> bool {
        self.switches.iter().any(|s| s == name)
    }
}

fn dispatch() -> Result<(), String> {
    let args = Args::parse()?;
    match args.command.as_str() {
        "version" | "--version" => {
            println!("netd {} (schema 1)", env!("CARGO_PKG_VERSION"));
            Ok(())
        }
        "help" | "--help" | "-h" => {
            println!("{}", HELP);
            Ok(())
        }
        "check" => {
            let cfg = load(&args)?;
            print!("{}", report::summary(&cfg));
            println!(
                "\nconfig ok: {} pools, {} reservations, {} names",
                cfg.dhcp.pools.len(),
                cfg.dhcp.reservations.len(),
                cfg.dns.records.len()
            );
            Ok(())
        }
        "show" => {
            let cfg = load(&args)?;
            print!("{}", report::summary(&cfg));
            Ok(())
        }
        "explain" => {
            let cfg = load(&args)?;
            let state = match args.flag("state") {
                Some(s) => PathBuf::from(s),
                None => cfg.state_dir.join("leases.json"),
            };
            let explain = report::ExplainArgs {
                interface: args.req("interface")?.to_string(),
                mac: args.req("mac")?.to_string(),
                client_id: args.flag("client-id").map(str::to_string),
                requested: args.flag("requested").map(str::to_string),
                hostname: args.flag("hostname").map(str::to_string),
                request: args.has("request"),
            };
            print!("{}", report::explain(&cfg, &state, &explain)?);
            Ok(())
        }
        "probe" => {
            let cfg = load(&args)?;
            let mac = match args.flag("mac") {
                Some(m) => m.to_string(),
                None => throwaway_mac(),
            };
            probe::run(&probe::ProbeArgs {
                interface: args
                    .flag("interface")
                    .map(str::to_string)
                    .or_else(|| cfg.dhcp.interfaces.first().cloned())
                    .ok_or("--interface is required (and the config has no DHCP interfaces)")?,
                mac,
                timeout: Duration::from_secs(
                    args.flag("timeout")
                        .unwrap_or("4")
                        .parse()
                        .map_err(|_| "--timeout is seconds")?,
                ),
                verbose: args.has("verbose"),
            })
        }
        "leases" => {
            let cfg = load(&args)?;
            let (db, warning) = LeaseDb::load(&cfg.state_dir);
            if let Some(w) = warning {
                eprintln!("netd: {w}");
            }
            println!("{}", db.to_json(util::now()));
            Ok(())
        }
        "query" => {
            let server: std::net::SocketAddr = args
                .flag("server")
                .unwrap_or("127.0.0.1:53")
                .parse()
                .map_err(|_| "--server is address:port")?;
            let qtype = match args
                .flag("type")
                .unwrap_or("A")
                .to_ascii_uppercase()
                .as_str()
            {
                "A" => dns::TYPE_A,
                "AAAA" => dns::TYPE_AAAA,
                "PTR" => dns::TYPE_PTR,
                "SOA" => dns::TYPE_SOA,
                "NS" => dns::TYPE_NS,
                "ANY" => dns::TYPE_ANY,
                other => return Err(format!("--type {other} is not A/AAAA/PTR/SOA/NS/ANY")),
            };
            let name = args.req("name")?;
            let reply = dns_server::query(server, name, qtype, Duration::from_secs(5))?;
            println!("{}", report::describe_dns(&reply));
            println!("  rcode        {}", reply.rcode());
            for r in &reply.answers {
                println!(
                    "  {} {} {} {}",
                    r.name,
                    dns::type_name(r.rtype),
                    r.ttl,
                    dns::rdata_address(r)
                        .map(|a| a.to_string())
                        .unwrap_or_else(|| format!("{} bytes", r.rdata.len()))
                );
            }
            Ok(())
        }
        "run" | "serve" => serve(&args),
        other => Err(format!("unknown command `{other}` (try --help)")),
    }
}

fn load(args: &Args) -> Result<Config, String> {
    let path = PathBuf::from(args.flag("config").unwrap_or("/etc/netd/config.json"));
    Config::load(&path)
}

fn serve(args: &Args) -> Result<(), String> {
    let cfg = Arc::new(load(args)?);
    let verbose = args.has("verbose") || args.has("debug");
    let (db, warning) = LeaseDb::load(&cfg.state_dir);
    if let Some(w) = warning {
        eprintln!("netd: {w} — starting with an empty lease table; addresses already handed out will be offered again");
    }
    println!(
        "netd: {} starting — zone {}, {} lease(s) restored, api {}",
        env!("CARGO_PKG_VERSION"),
        cfg.zone,
        db.len(),
        api::api_addr(&cfg)
    );
    if !sys::CAN_SERVE {
        return Err(sys::describe_unsupported_platform().into());
    }
    let db = Arc::new(Mutex::new(db));
    let stats = Arc::new(Stats::default());
    stats.set_started(util::now());

    let dns = Dns::new(cfg.clone(), db.clone(), stats.clone());
    {
        let dns = dns.clone();
        std::thread::Builder::new()
            .name("dns".into())
            .spawn(move || {
                if let Err(e) = dns.serve() {
                    eprintln!("netd: dns stopped: {e}");
                }
            })
            .map_err(|e| format!("spawning the dns thread: {e}"))?;
    }
    {
        let api = Arc::new(api::Api {
            cfg: cfg.clone(),
            db: db.clone(),
            stats: stats.clone(),
            dns: dns.clone(),
        });
        std::thread::Builder::new()
            .name("api".into())
            .spawn(move || {
                if let Err(e) = api.clone().serve() {
                    eprintln!("netd: api stopped: {e}");
                }
            })
            .map_err(|e| format!("spawning the api thread: {e}"))?;
    }
    {
        if args.has("no-dhcp") {
            println!("netd: dhcp DISABLED by --no-dhcp (port 67 is not opened)");
        } else {
            let (cfg, db, stats) = (cfg.clone(), db.clone(), stats.clone());
            std::thread::Builder::new()
                .name("dhcp".into())
                .spawn(move || {
                    if let Err(e) = dhcp_server::run(cfg, db, stats, verbose) {
                        eprintln!("netd: dhcp stopped: {e}");
                    }
                })
                .map_err(|e| format!("spawning the dhcp thread: {e}"))?;
        }
    }
    {
        if args.has("no-ra") {
            println!("netd: router advertisements DISABLED by --no-ra (no ICMPv6 socket is opened)");
        } else {
            let (cfg, stats) = (cfg.clone(), stats.clone());
            std::thread::Builder::new()
                .name("ra".into())
                .spawn(move || ra::run(cfg, stats))
                .map_err(|e| format!("spawning the ra thread: {e}"))?;
        }
    }

    // Housekeeping: persist the snapshot and prune. One thread, one second
    // ticks, so a lease is on disk within a second of being granted and a
    // restart cannot hand the same address out twice in a way a person could
    // notice. The snapshot is the *only* thing this daemon writes.
    let mut last_prune = std::time::Instant::now();
    loop {
        std::thread::sleep(Duration::from_secs(1));
        let at = util::now();
        if let Ok(mut g) = db.lock() {
            g.save(&cfg.state_dir, at);
            if last_prune.elapsed() >= Duration::from_secs(300) {
                let removed = g.prune(at);
                if removed > 0 {
                    println!("netd: pruned {removed} lease(s) expired for over a day");
                }
                last_prune = std::time::Instant::now();
            }
        }
    }
}

/// A MAC for `probe` that cannot collide with a real device: the
/// locally-administered bit is set and the rest is the pid and the clock, so two
/// probes in one second differ.
fn throwaway_mac() -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.subsec_nanos())
        .unwrap_or(0);
    let pid = std::process::id();
    format!(
        "02:00:{:02x}:{:02x}:{:02x}:{:02x}",
        (pid >> 8) as u8,
        pid as u8,
        (nanos >> 8) as u8,
        nanos as u8
    )
}

const HELP: &str = "\
netd — DHCPv4, IPv6 router advertisements and DNS for one network, from one config

usage: netd <command> [--config PATH] [options]

commands
  run       serve (the default)                          --config, --verbose,
                                                          --no-dhcp, --no-ra
  check     validate the config and print what it would do
  show      the same summary as check, without the verdict
  explain   what would be offered to one client          --interface --mac
                                                          [--client-id --requested --hostname --request]
  probe     a whole DHCP cycle against whatever answers  --interface [--mac --timeout]
  leases    the persisted snapshot
  query     ask a DNS server a question                  --server --name [--type]
  version   print the schema version
";
